.gzp-desk{
          tło:
            gradient promieniowy (120% 70% przy 50% 0%, rgba(214.178.110,.05), przezroczysty 58%),
            gradient promieniowy (130% 100% przy 50% 108%, rgba(0,0,0,.34), przezroczysty 62%),
            /* słoje drewna — szeroko i nieregularnie rozmieszczone (stare linie włosa
               Wyglądało jak aksamit) */
            powtarzalny gradient liniowy (92 stopnie,
              rgba(0,0,0,.13) 0 3px,
              przezroczysty 3px 17px,
              rgba(255,255,255,.016) 17px 20px,
              przezroczysty 20px 41px,
              rgba(0,0,0,.09) 41px 43px,
              przezroczysty 43px 74px),
            /*połączenia desek */
            powtarzalny gradient liniowy (90 stopni,
              rgba(0,0,0,.42) 0 2px,
              przezroczysty 2px 148px),
            gradient liniowy (180 stopni, #33261a 0%, #291e13 52%, #1c150d 100%);
        }
        .gzp-pod{
          pozycja: absolutna;
          wstawka: 0;
          tło: gradient liniowy (180 stopni, #e6d9b6 0%, #d6c599 100%);
          box-shadow: 0 12px 22px rgba(0,0,0,.45), wstawka 0 0 0 1px rgba(120,90,36,.2);
          transformacja: obrót (-1,15 stopnia) tłumaczenie Y (5 pikseli);
        }
        .gzp-under--2{
          tło: gradient liniowy (180 stopni, #e1d2ab 0%, #cfbd90 100%);
          transformacja: obrót (0,85 stopnia) tłumaczenie Y (9 pikseli);
        }
